  indigo: "#3B2EE5",   // primary bold blue
  indigoDeep: "#2418C7",
  pink: "#EE3A8A",     // hot pink
  pinkSoft: "#F4BFD9", // pastel pink
  pinkBg: "#FFF1F7",
  lavender: "#B5A4F0",
