// ---------------- Bonnie mascot (real PNG assets) ----------------
const BONNIE_HAPPY = "data:image/png;base64,";
const BONNIE_EXCITED = "data:image/png;base64,";

const Bonnie = ({ size = 72, mood = "happy" }) => {
  const src = mood === "excited" ? BONNIE_EXCITED : BONNIE_HAPPY;
  return (
    <img
      src={src}
      alt="Bonnie"
      width={size}
      height={size}
      style={{
        width: size,
        height: size,
        objectFit: "contain",
        display: "inline-block",
        userSelect: "none",
        pointerEvents: "none",
      }}
      draggable={false}
    />
  );
};

// ---------------- Sparkle icon (brand-style) ----------------
const Spark = ({ size = 14, color = C.indigo }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path
      d="M12 1 L14 10 L23 12 L14 14 L12 23 L10 14 L1 12 L10 10 Z"
      fill={color}
    />
  </svg>
);

